"""Maintenance deadlines, document warnings, and the vehicle status rules around bookings."""
import sys, os, re, json, subprocess, datetime as dt
sys.path.insert(0, os.path.dirname(__file__))
from driver import *
env = open(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), ".env")).read()
AE = re.search(r"^ADMIN_EMAIL=(.*)$", env, re.M).group(1).strip('"'); AP = re.search(r"^ADMIN_PASSWORD=(.*)$", env, re.M).group(1).strip('"')
for jar, e, p in [("/tmp/jm_a", AE, AP), ("/tmp/jm_o", "demo.owner@example.com", "Demo-pass-2030!")]: login(jar, e, p)
A, O = "/tmp/jm_a", "/tmp/jm_o"
reg = find_form(get(None, "/register"), has=["name", "email", "password", "role"])
def fresh(i):
    jar, em = f"/tmp/jm_u{i}", f"mnt.user{i}@example.test"; open(jar, "w").close()
    submit(jar, "/register", reg, {"name": f"Mnt User {i}", "email": em, "password": "parola-lunga-1", "role": "CUSTOMER"}); login(jar, em, "parola-lunga-1")
    return jar, {"fullName": f"Mnt User {i}", "email": em, "phone": "0700000000"}
def post(u, vid, day):
    d = lambda h: (dt.datetime.now(dt.timezone.utc) + dt.timedelta(days=day)).replace(hour=h, minute=0, second=0, microsecond=0).strftime("%Y-%m-%dT%H:%M:%S.000Z")
    out = subprocess.run(["curl", "-s", "-o", "/tmp/m.out", "-w", "%{http_code}", "-X", "POST", "-H", "Content-Type: application/json", "-d", json.dumps({"vehicleId": vid, "startAt": d(8), "endAt": d(10), "customer": u[1]}), "-b", u[0], BASE + "/api/bookings"], capture_output=True, text=True).stdout
    return out, open("/tmp/m.out").read()

print("== DOCUMENT WARNINGS")
v = sql("select id from vehicles where owner_id is null and category='NAKED_SPORT' limit 1"); name = sql(f"select name from vehicles where id='{v}'")
sql(f"delete from maintenance where vehicle_id='{v}'")
adm = text(get(A, "/admin/maintenance"))
check("a vehicle with no ITP, RCA or service record is flagged as missing", name in adm and "missing" in adm.lower())
sql(f"insert into maintenance(id,vehicle_id,type,performed_at,next_due_at) values ('m_itp','{v}','ITP', now() - interval '400 days', now() - interval '35 days')")
sql(f"insert into maintenance(id,vehicle_id,type,performed_at,next_due_at) values ('m_rca','{v}','RCA', now() - interval '350 days', now() + interval '10 days')")
sql(f"insert into maintenance(id,vehicle_id,type,performed_at,next_due_at) values ('m_svc','{v}','SERVICE', now() - interval '30 days', now() + interval '300 days')")
adm = text(get(A, "/admin/maintenance"))
check("an ITP that expired 35 days ago is shown as overdue", re.search(re.escape(name) + r".{0,200}ITP: overdue since", adm) is not None, adm[adm.find(name):adm.find(name) + 250])
check("an RCA expiring in 10 days is shown as due soon", re.search(re.escape(name) + r".{0,300}RCA: due", adm) is not None)
check("a service with a far deadline raises no warning", "SERVICE: due" not in adm[adm.find(name):adm.find(name) + 400] and "Service: due" not in adm[adm.find(name):adm.find(name) + 400])
check("the admin overview counts vehicles with document problems", re.search(r"Vehicles with document problems\s*\d+", text(get(A, "/admin"))) is not None)
u0 = fresh(0)
code, body = post(u0, v, 20)
check("a document warning never blocks a booking (the vehicle can still be booked)", code == "201", (code, body[:80]))

print("== IN SERVICE")
bid = sql(f"select id from bookings where vehicle_id='{v}' and status='PENDING' limit 1")
submit(A, f"/admin/bookings/{bid}", find_form(get(A, f"/admin/bookings/{bid}"), has=["bookingId", "reason"]), {}, button=("to", "CONFIRMED"))
sql(f"update vehicles set status='IN_SERVICE' where id='{v}'")
code, body = post(fresh(1), v, 22)
check("a vehicle in service cannot be booked (vehicle_unavailable)", code == "404" and "vehicle_unavailable" in body, (code, body[:80]))
check("it disappears from the catalog", name not in text(get(None, "/vehicles?q=" + name.split()[0])) or f"View {name}" not in get(None, "/vehicles?q=" + name.split()[0]))
check("the booking was confirmed while the vehicle was available", sql(f"select status from bookings where id='{bid}'") == "CONFIRMED")
sql(f"update vehicles set status='IN_SERVICE' where id='{v}'")
sql(f"update bookings set start_at = now() - interval '5 minutes', end_at = now() + interval '115 minutes' where id='{bid}'")
r = submit(A, f"/admin/bookings/{bid}", find_form(get(A, f"/admin/bookings/{bid}"), has=["bookingId", "reason"]), {}, button=("to", "ACTIVE"))
check("a vehicle in service cannot be handed over", "error=VEHICLE_NOT_BOOKABLE" in r and sql(f"select status from bookings where id='{bid}'") == "CONFIRMED", r)
check("the existing booking was not cancelled by the status change", sql(f"select status from bookings where id='{bid}'") == "CONFIRMED")
own = sql("select id from vehicles where owner_id=(select id from users where email='demo.owner@example.com') and status='AVAILABLE' limit 1")
form = find_form(get(O, f"/provider/vehicles/{own}?tab=details"), has=["vehicleId"])
check("an owner has no control that changes the vehicle status", not any(re.search(r"IN_SERVICE|RETIRED|Put in service", text(get(O, f'/provider/vehicles/{own}?tab={t}'))) for t in ("details", "photos", "maintenance", "bookings")))
vp = get(A, f"/admin/vehicles/{v}"); chg = find_form(vp, has=["vehicleId", "to"])
r = submit(A, f"/admin/vehicles/{v}", chg, {"to": "AVAILABLE"})
check("only the admin brings it back to AVAILABLE, explicitly", sql(f"select status from vehicles where id='{v}'") == "AVAILABLE", r)
r = submit(A, f"/admin/bookings/{bid}", find_form(get(A, f"/admin/bookings/{bid}"), has=["bookingId", "reason"]), {}, button=("to", "ACTIVE"))
check("after that the handover works", sql(f"select status from bookings where id='{bid}'") == "ACTIVE", r)
check("RENTED is derived: the admin list shows the vehicle as rented while the stored status stays AVAILABLE", "Rented now" in text(get(A, "/admin/vehicles?q=" + name.split()[0])) and sql(f"select status from vehicles where id='{v}'") == "AVAILABLE")
r = submit(A, f"/admin/vehicles/{v}", find_form(get(A, f"/admin/vehicles/{v}"), has=["vehicleId", "to"]), {"to": "RETIRED"})
check("a vehicle that is out with a customer cannot be retired", sql(f"select status from vehicles where id='{v}'") == "AVAILABLE" and "error=VEHICLE_RENTED" in r, r)
submit(A, f"/admin/bookings/{bid}", find_form(get(A, f"/admin/bookings/{bid}"), has=["bookingId", "reason"]), {}, button=("to", "COMPLETED"))
check("completing the booking leaves the stored status alone", sql(f"select status from vehicles where id='{v}'") == "AVAILABLE")

print("== EDIT A MAINTENANCE RECORD")
# the owner adds a record through the real form, then edits it through the real edit form
add_form = find_form(get(O, f"/provider/vehicles/{own}?tab=maintenance"), has=["vehicleId", "performedOn"])
check("the maintenance tab has an add form and no edit form until a record is chosen", add_form is not None and "recordId" not in [n for n, _, _ in add_form["fields"]])
submit(O, f"/provider/vehicles/{own}", add_form, {"type": "SERVICE", "performedOn": "2030-03-01", "nextDueOn": "2031-03-01", "notes": "first entry"})
rec = sql(f"select id from maintenance where vehicle_id='{own}' and notes='first entry'")
check("the record was stored", rec != "")
page = get(O, f"/provider/vehicles/{own}?tab=maintenance&edit={rec}")
edit_form = find_form(page, has=["recordId", "performedOn"])
check("the edit link opens a form prefilled with the record", edit_form is not None and dict((n, v) for n, v, _ in edit_form["fields"]).get("performedOn") == "2030-03-01" and "first entry" in page and "Edit the record" in page)
r = submit(O, f"/provider/vehicles/{own}", edit_form, {"type": "RCA", "performedOn": "2030-03-05", "nextDueOn": "2031-03-05", "notes": "corrected"})
check("saving the edit changes the same row (type, dates, notes) and creates no new one", sql(f"select type||'|'||((performed_at at time zone 'UTC') at time zone 'Europe/Bucharest')::date||'|'||((next_due_at at time zone 'UTC') at time zone 'Europe/Bucharest')::date||'|'||notes from maintenance where id='{rec}'") == "RCA|2030-03-05|2031-03-05|corrected" and sql(f"select count(*) from maintenance where vehicle_id='{own}' and notes in ('first entry','corrected')") == "1", r)
check("a success message is shown", "maintenance record was saved" in text(get(O, f"/provider/vehicles/{own}?tab=maintenance&ok=maintenance_updated")))
r = submit(O, f"/provider/vehicles/{own}", edit_form, {"performedOn": "2030-03-05", "nextDueOn": "2030-03-01", "notes": "bad dates"})
check("a deadline before the date done is refused and nothing changes", "error=maintenance_dates" in r and sql(f"select notes from maintenance where id='{rec}'") == "corrected", r)
r = submit(O, f"/provider/vehicles/{own}", edit_form, {"performedOn": "not-a-date"})
check("an invalid date is refused", "error=maintenance_invalid" in r and sql(f"select notes from maintenance where id='{rec}'") == "corrected", r)
r = submit(O, f"/provider/vehicles/{own}", edit_form, {"type": "HACK", "performedOn": "2030-03-05"})
check("an invented type is refused", "error=maintenance_invalid" in r and sql(f"select type from maintenance where id='{rec}'") == "RCA", r)
oth = "/tmp/jm_o2"; login(oth, "demo.company@example.com", "Demo-pass-2030!")
r = submit(oth, "/provider/vehicles", edit_form, {"notes": "hijack"})
check("another provider cannot edit it by sending the form themselves", sql(f"select notes from maintenance where id='{rec}'") == "corrected", r)
co_v = sql("select id from vehicles where owner_id=(select id from users where email='demo.company@example.com') limit 1")
check("the edit link of a foreign record shows no edit form", find_form(get(oth, f"/provider/vehicles/{co_v}?tab=maintenance&edit={rec}"), has=["recordId", "performedOn"]) is None)
check("nor does a foreign vehicle page open for the owner", status(O, f"/provider/vehicles/{co_v}?tab=maintenance&edit={rec}").startswith("404"))
before_status = sql(f"select status from vehicles where id='{own}'")
a_form = find_form(get(A, f"/admin/vehicles/{own}?tab=maintenance&edit={rec}"), has=["recordId", "performedOn"])
submit(A, f"/admin/vehicles/{own}", a_form, {"notes": "admin note"})
check("an admin can edit it too, and the vehicle status is untouched", sql(f"select notes from maintenance where id='{rec}'") == "admin note" and sql(f"select status from vehicles where id='{own}'") == before_status)
cust = "/tmp/jm_c"; login(cust, "demo.customer@example.com", "Demo-pass-2030!")
submit(cust, "/provider/vehicles", edit_form, {"notes": "customer hijack"})
check("a customer cannot edit it", sql(f"select notes from maintenance where id='{rec}'") == "admin note")
print("FAILS:", FAILS)
